import os
import math
import inspect

import torch
import torch.distributed as dist


def _get_rank_size():
    rank = dist.get_rank()
    world_size = dist.get_world_size()
    return rank, world_size


def _llama_attrs(model):
    if hasattr(model, "model") and hasattr(model.model, "layers"):
        layers = model.model.layers
        transformer = model.model
        lm_head = getattr(model, "lm_head", None)
    elif hasattr(model, "layers"):
        layers = model.layers
        transformer = model
        lm_head = getattr(model, "lm_head", None)
    else:
        raise ValueError("Unsupported LLaMA model layout")

    config = getattr(model, "config", None) or getattr(transformer, "config", None)
    return config, transformer, layers, lm_head


def _layer_range(world_size, rank, num_layers):
    base = num_layers // world_size
    rem = num_layers % world_size
    start = rank * base + min(rank, rem)
    end = start + base + (1 if rank < rem else 0)
    return start, end


def _maybe_require(grad, requires):
    if requires:
        grad.requires_grad_(True)
    return grad


def _send_recv_tensors(rank, world_size, send_buf, recv_buf, is_first, is_last):
    ops = []
    if not is_last and send_buf is not None:
        ops.append(dist.P2POp(dist.isend, send_buf, rank + 1))
    if not is_first:
        if recv_buf is None:
            ops.append(dist.P2POp(dist.irecv, rank - 1))
        else:
            ops.append(dist.P2POp(dist.irecv, recv_buf, rank - 1))

    reqs = dist.batch_isend_irecv(ops) if ops else []
    for req in reqs:
        req.wait()


def _forward_first_stage(model, transformer, layers, start, end, x, inputs_embeds):
    hidden = inputs_embeds
    for i in range(start, end):
        layer = layers[i]
        hidden = layer(hidden, None)[0] if isinstance(hidden, tuple) else layer(hidden)
    return hidden


def _forward_stage(layers, start, end, hidden):
    for i in range(start, end):
        layer = layers[i]
        hidden = layer(hidden, None)[0] if isinstance(hidden, tuple) else layer(hidden)
    return hidden


def _make_recv_buffer(shape, dtype, device):
    return torch.empty(shape, dtype=dtype, device=device)


def _compute_logits_and_loss(model, transformer, lm_head, hidden, targets, num_microbatches):
    features = hidden

    norm = getattr(transformer, "norm", None)
    if norm is not None and not hasattr(lm_head, "norm"):
        features = norm(features)

    if lm_head is not None:
        logits = lm_head(features)
    else:
        logits = model.lm_head(features) if hasattr(model, "lm_head") else None
        if logits is None:
            head = getattr(transformer, "lm_head", None)
            logits = head(features)

    loss = torch.nn.functional.cross_entropy(
        logits.view(-1, logits.size(-1)),
        targets.view(-1).to(logits.device),
        ignore_index=-100,
        reduction="mean",
    )
    loss = loss.to(hidden.dtype) / num_microbatches
    return loss, logits


def _grad_from_loss(loss):
    return torch.ones_like(loss, requires_grad=True)


def train_step_pipeline_afab(model, inputs, targets, device, dtype):
    """Train one step with all-forward-all-backward pipeline parallel scheduling.

    Args:
        model: LlamaForCausalLM instance.
        inputs: list of input ID microbatch tensors.
        targets: list of target ID microbatch tensors.
        device: torch device string or torch.device.
        dtype: torch dtype.
    """
    assert dist.is_available() and dist.is_initialized(), "torch.distributed must be initialized"
    rank, world_size = _get_rank_size()
    device = torch.device(device)

    config, transformer, layers, lm_head = _llama_attrs(model)
    num_layers = len(layers)
    start, end = _layer_range(world_size, rank, num_layers)
    num_microbatches = len(inputs)

    is_first = rank == 0
    is_last = rank == world_size - 1

    # Move input/target microbatches to this device.  No model copies are made.
    if is_first:
        input_ids = [t.to(device=device, dtype=torch.long) for t in inputs]
    else:
        input_ids = None

    if is_last:
        target_ids = [t.to(device=device, dtype=torch.long) for t in targets]
    else:
        target_ids = None

    # Determine hidden size from config or embed weight shape.
    hidden_size = None
    if config is not None:
        hidden_size = getattr(config, "hidden_size", None)
    if hidden_size is None:
        embed_tokens = getattr(transformer, "embed_tokens", None) or getattr(model, "embed_tokens", None)
        if embed_tokens is not None:
            hidden_size = embed_tokens.weight.size(-1)
        elif num_layers > 0:
            hidden_size = layers[0].self_attn.q_proj.weight.size(-1) // getattr(config, "num_attention_heads", 1)
        else:
            raise ValueError("Could not determine hidden_size")

    # Forward all microbatches.
    hidden_states = []  # tensors needing backward on this rank
    send_buffers = []
    recv_buffers = []

    for mb in range(num_microbatches):
        if is_first:
            # LLaMA first stage needs embeddings + first layers.
            embed_tokens = getattr(transformer, "embed_tokens", None) or getattr(model, "embed_tokens", None)
            if embed_tokens is None:
                raise ValueError("Could not find input embeddings")
            ids = input_ids[mb]
            hidden = embed_tokens(ids).to(device=device, dtype=dtype)
            hidden.requires_grad_(True)
            for i in range(start, end):
                layer = layers[i]
                out = layer(hidden, None)
                hidden = out[0] if isinstance(out, tuple) else out
            hidden_states.append(hidden)
        else:
            recv_shape = None
            # Peek at input shape if possible to infer microbatch/seq_len.
            if inputs is not None and len(inputs) > mb:
                recv_shape = tuple(inputs[mb].shape[:2]) + (hidden_size,)
            else:
                recv_shape = (1, 1, hidden_size)
            recv_buf = _make_recv_buffer(recv_shape, dtype, device)
            _send_recv_tensors(rank, world_size, None, recv_buf, is_first, is_last)
            hidden = recv_buf
            hidden.requires_grad_(True)
            for i in range(start, end):
                layer = layers[i]
                out = layer(hidden, None)
                hidden = out[0] if isinstance(out, tuple) else out
            hidden_states.append(hidden)

        if is_last:
            loss, logits = _compute_logits_and_loss(model, transformer, lm_head, hidden, target_ids[mb], num_microbatches)
            hidden_states[-1] = loss
        else:
            send_buf = hidden_states[-1]
            if send_buf.is_contiguous():
                send_buf = send_buf
            else:
                send_buf = send_buf.detach().clone().contiguous()
                hidden_states[-1] = send_buf
                # TODO: maintain graph for backward; but contiguous clone detaches.
            # Ensure contiguous send without losing autograd link.
            send_buf = hidden_states[-1].contiguous()
            hidden_states[-1] = send_buf
            _send_recv_tensors(rank, world_size, send_buf.detach(), None, is_first, is_last)

    # Backward all microbatches.
    for mb in range(num_microbatches):
        if is_last:
            loss = hidden_states[mb]
            grad_out = _grad_from_loss(loss)
            loss.backward(grad_out)
        else:
            # Send buffer is output of this stage's forward.
            out = hidden_states[mb]
            # We cannot propagate gradient into incoming hidden state through P2P directly;
            # receive gradient for this microbatch and run backward from out.
            grad_shape = out.shape
            grad_buf = _make_recv_buffer(grad_shape, dtype, device)
            _send_recv_tensors(rank, world_size, None, grad_buf, is_first, is_last)
            grad_buf.requires_grad_(False)
            # If incoming hidden had requires_grad, backward into layer params.
            # Use grad_buf as upstream gradient.
            # Need autograd from out to incoming hidden and params.
            if getattr(out, "grad_fn", None) is not None:
                out.backward(grad_buf)
            else:
                # Recreate graph if needed by re-running with grad enabled.
                pass

    return None
